<!doctype html>
<html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پنل مدیریت هم‌قدم</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800&display=swap');
:root{font-family:Vazirmatn,Tahoma,sans-serif;color:#172b3a;background:#f4f7f9;font-synthesis:none}*{box-sizing:border-box}body{margin:0;font-family:inherit}button,input,select,textarea{font:inherit}header{height:76px;background:#fff;color:#172b3a;padding:0 30px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e6edf1;position:sticky;top:0;z-index:10}header h1{font-size:17px;font-weight:800;margin:0;display:flex;align-items:center;gap:12px}header h1:before{content:'🤝';display:grid;place-items:center;background:#146c5a;color:white;width:38px;height:38px;border-radius:12px;font-size:21px}.wrap{max-width:1600px;margin:0 auto;padding:28px;display:block}.card{background:#fff;border:1px solid #e8eef1;border-radius:17px;padding:22px;margin-bottom:18px;box-shadow:0 5px 20px #18374708}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:16px}.metric{font-size:30px;font-weight:800;color:#146c5a;margin-top:10px}.tabs{width:245px;float:right;display:flex;flex-direction:column;gap:7px;margin-left:24px;position:sticky;top:100px}.tabs button,button{border:0;border-radius:10px;padding:11px 16px;background:#146c5a;color:white;cursor:pointer;font-weight:600;transition:.18s}button:hover{filter:brightness(.95);transform:translateY(-1px)}.tabs button{background:transparent;color:#526675;text-align:right;padding:13px 15px;border-radius:11px}.tabs button:before{content:'›';font-size:19px;margin-left:10px;color:#8ca39d}.tabs button.active{background:#e8f3ef;color:#105b4c;font-weight:800}.tabs button.active:before{color:#146c5a}.tab{margin-right:269px}.tab.hidden{display:none}.tabs:after{content:'مدیریت یکپارچه مشارکت‌های فرهنگی';font-size:11px;color:#91a0aa;padding:20px 12px;line-height:2}input,select,textarea{width:100%;padding:12px 14px;border:1px solid #dce5e9;border-radius:10px;background:#fbfcfd;margin:7px 0 15px;outline:none;transition:.15s}input:focus,select:focus,textarea:focus{border-color:#3c9a83;box-shadow:0 0 0 3px #3c9a8318;background:#fff}label{font-size:12px;color:#526675;font-weight:700;display:block}.row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.muted{color:#81909a;font-size:12px}.hidden{display:none!important}.msg{padding:12px 15px;border-radius:10px;background:#eaf6f0;color:#17634e;margin:12px 0}.danger{background:#fff0f0;color:#9c2424}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.actions button.secondary,button.secondary{background:#eef2f4;color:#526675}.section-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.section-title h2,.card h2{font-size:19px;font-weight:800;margin:0 0 8px}.card h3{font-size:15px;font-weight:800;margin:20px 0 14px}.pill{background:#edf3f0;padding:5px 10px;border-radius:20px;font-size:11px}table{width:100%;border-collapse:separate;border-spacing:0}td,th{text-align:right;border-bottom:1px solid #edf1f3;padding:14px 12px;font-size:12px}th{background:#f7f9fa;color:#61727e;font-weight:800}tr:last-child td{border-bottom:0}.section-title button{white-space:nowrap}.login-screen{max-width:460px;margin:8vh auto!important;padding:38px!important}.login-screen h2{font-size:23px;margin:0 0 8px}.login-screen .brand-mark{width:54px;height:54px;background:#e7f3ee;color:#146c5a;border-radius:16px;display:grid;place-items:center;font-size:27px;font-weight:800;margin-bottom:24px}.loader{position:fixed;inset:0;background:#ffffffed;z-index:99;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px}.loader .track{width:230px;height:5px;background:#e4ece9;border-radius:8px;overflow:hidden}.loader .bar{height:100%;width:35%;background:#16836b;border-radius:8px;animation:progress 1.1s ease-in-out infinite}@keyframes progress{0%{transform:translateX(220%)}100%{transform:translateX(-320%)}}.loader p{font-size:13px;color:#61727e;margin:0}.metrics-card{position:relative;overflow:hidden}.metrics-card:after{content:'';position:absolute;width:65px;height:65px;border-radius:50%;background:#e9f4ef;left:-18px;top:-18px}.table-wrap{overflow:auto;border:1px solid #edf1f3;border-radius:12px}.modal{position:fixed;inset:0;background:#102b3b88;z-index:50;display:grid;place-items:center;padding:18px}.modal-card{width:min(650px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:18px;padding:24px;box-shadow:0 20px 60px #102b3b33}.primary-note{background:#f0f7f4;border-right:3px solid #16836b;padding:13px 15px;border-radius:8px;color:#526675;font-size:12px;line-height:2}@media(max-width:900px){.wrap{padding:16px}.tabs{width:auto;float:none;position:static;flex-direction:row;overflow:auto;margin:0 0 18px}.tabs button{white-space:nowrap}.tabs:after{display:none}.tab{margin:0}}@media(max-width:600px){header{height:65px;padding:0 14px}header h1{font-size:13px}.wrap{padding:12px}.card{padding:16px}.row{grid-template-columns:1fr}.login-screen{margin:6vh auto!important;padding:24px!important}.tabs button{font-size:12px;padding:10px}.metric{font-size:24px}}

/* تکمیل هویت بصری و آیکون‌های معنادار */
.tabs button:before{content:none!important}.tabs button{display:flex;align-items:center;gap:12px}.nav-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:9px;background:#f0f4f2;font-size:16px;flex:none}.tabs button.active .nav-icon{background:#d5eae2}.quick-action{background:#fff!important;color:#193b35!important;border:1px solid #e2ece7!important;border-radius:15px!important;min-height:118px;text-align:right;display:flex;flex-direction:column;align-items:flex-start;gap:7px;padding:18px!important;box-shadow:0 5px 20px #18374708}.quick-action:hover{border-color:#91c9b5!important;background:#f8fcfa!important}.qa-icon{font-size:25px}.quick-action small{font-size:11px;color:#81909a;font-weight:400}.brand-mark{background:linear-gradient(145deg,#146c5a,#24977c)!important;color:#fff!important;box-shadow:0 8px 20px #146c5a30}.login-screen{border-top:4px solid #16836b}.tabs{background:#fff;border:1px solid #e8eef1;border-radius:17px;padding:13px;min-height:calc(100vh - 125px)}@media(max-width:900px){.tabs{min-height:0}}
.jalali-picker{position:fixed;z-index:1000;width:290px;background:#fff;border:1px solid #dbe7e1;border-radius:14px;box-shadow:0 14px 40px #18374725;padding:12px;font-family:Vazirmatn,Tahoma,sans-serif}.jalali-picker .jp-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:9px}.jalali-picker .jp-head button{padding:6px 10px}.jalali-picker .jp-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:3px}.jalali-picker .jp-grid span{text-align:center;font-size:11px;color:#71847b;padding:6px 0}.jalali-picker .jp-grid button{padding:7px 0;border-radius:8px;background:#f5f8f6;color:#254b3e;font-size:12px}.jalali-picker .jp-grid button:hover,.jalali-picker .jp-grid button.selected{background:#146c5a;color:#fff}.jalali-picker .jp-foot{display:flex;justify-content:space-between;margin-top:8px}.jalali-picker .jp-foot button{background:#edf3f0;color:#456357;font-size:11px;padding:6px 9px}
</style>

</head><body>
<header><h1>سامانه مدیریت مشارکت‌های فرهنگی هم‌قدم</h1><div class="actions"><span id="who" class="muted" style="color:#dcebe5"></span><button id="logout" class="secondary hidden" onclick="logout()">خروج</button></div></header>
<div class="wrap">
<section id="login" class="card login-screen"><div class="brand-mark">🤝</div><h2>ورود به سامانه هم‌قدم</h2><p class="muted">سامانه مدیریت مشارکت‌های فرهنگی</p><label>ایمیل</label><input id="email" type="email" value="" placeholder="admin@example.com"><label>رمز عبور</label><input id="password" type="password" placeholder="رمز عبور"><button id="loginButton" style="width:100%" onclick="login()">ورود به پنل</button><div id="loginMsg" class="muted"></div></section>
<section id="app" class="hidden">
<div class="tabs"><button class="active" data-tab="dashboard"><span class="nav-icon">🏠</span>میز کار و داشبورد</button><button data-tab="universities" id="universitiesNav" class="hidden"><span class="nav-icon">🏛️</span>دانشگاه‌ها و مراکز</button><button data-tab="users" id="usersNav" class="hidden"><span class="nav-icon">👥</span>مدیریت مدیران و کاربران</button><button data-tab="events" id="eventsNav" class="hidden"><span class="nav-icon">🎪</span>برنامه‌های فرهنگی</button><button data-tab="reports"><span class="nav-icon">📊</span>گزارش‌ها و نظارت</button><button data-tab="notifications"><span class="nav-icon">🔔</span>اطلاع‌رسانی</button><button data-tab="albums"><span class="nav-icon">🖼️</span>آلبوم تصاویر</button></div>
<div id="dashboard" class="tab"><div class="section-title"><h2>نمای کلی</h2><button onclick="loadDashboard()">به‌روزرسانی</button></div><div id="metrics" class="grid"></div><div id="adminQuickActions" class="grid hidden"><button class="quick-action" onclick="openTab('universities')"><span class="qa-icon">🏛️</span><span>تعریف دانشگاه</span><small>ثبت و مدیریت مراکز دانشگاهی</small></button><button class="quick-action" onclick="openTab('users')"><span class="qa-icon">👥</span><span>تعریف و مدیریت کاربران</span><small>ایجاد مدیر فرهنگی و تعیین نقش‌ها</small></button><button class="quick-action" onclick="openTab('reports')"><span class="qa-icon">📊</span><span>گزارش‌های سامانه</span><small>نظارت بر عملکرد دانشگاه‌ها</small></button></div><div class="card"><h3>برنامه‌های ثبت‌شده برای نظارت</h3><div id="eventList" class="muted">در حال دریافت...</div></div></div>
<div id="universities" class="tab hidden"><div class="card"><div class="section-title"><div><h2>ساختار سازمانی | دانشگاه‌ها</h2><p class="muted">تعریف و نگهداری دانشگاه‌ها بر عهده مدیر ارشد سامانه است.</p></div><button onclick="loadUniversities()">به‌روزرسانی</button></div><div class="row"><div><label>نام دانشگاه</label><input id="uniName" placeholder="نام کامل دانشگاه"></div><div><label>کد دانشگاه</label><input id="uniCode" placeholder="کد یکتا"></div></div><div class="row"><div><label>شهر</label><input id="uniCity" placeholder="شهر محل دانشگاه"></div><div style="display:flex;align-items:end"><button onclick="saveUniversity()" id="uniSave">ثبت دانشگاه</button><button class="secondary hidden" id="uniCancel" onclick="resetUniversityForm()">انصراف</button></div></div><div id="uniMsg"></div><h3>فهرست دانشگاه‌ها</h3><div id="universitiesList" class="table-wrap">در حال دریافت...</div></div></div>
<div id="users" class="tab hidden"><div class="card"><div class="section-title"><h2>مدیریت کاربران و دسترسی‌ها</h2><button onclick="loadUsers()">به‌روزرسانی فهرست</button></div><p class="muted">ایجاد حساب، تعیین نقش و دانشگاه، ویرایش اطلاعات و فعال یا غیرفعال‌سازی حساب‌ها؛ این بخش فقط برای مدیر ارشد نمایش داده می‌شود.</p><h3>ایجاد کاربر جدید</h3><div class="row"><div><label>نام و نام خانوادگی</label><input id="newUserName"></div><div><label>ایمیل</label><input id="newUserEmail" type="email"></div><div><label>رمز عبور اولیه (حداقل ۸ کاراکتر)</label><input id="newUserPassword" type="password"></div></div><div class="row"><div><label>نقش</label><select id="newUserRole" onchange="toggleUserUniversity()"><option value="cultural_manager">مدیر فرهنگی</option><option value="student">دانشجو</option><option value="observer">ناظر</option></select></div><div id="newUniversityWrap"><label>دانشگاه / واحد</label><select id="newUserUniversity"></select></div></div><button onclick="createUser()">ایجاد حساب کاربری</button><div id="userFormMsg"></div><hr><div class="row"><div><label>جست‌وجوی نام یا ایمیل</label><input id="userSearch" placeholder="جست‌وجو..." onkeydown="if(event.key==='Enter')loadUsers()"></div><div style="align-self:end"><button onclick="loadUsers()">جست‌وجو</button></div></div><div id="usersList">برای نمایش کاربران، فهرست را بارگذاری کنید.</div><div id="userEditModal" class="modal hidden"><div class="modal-card"><div class="section-title"><h2>ویرایش حساب کاربری</h2><button class="secondary" onclick="closeUserModal()">بستن</button></div><input type="hidden" id="editUserId"><div class="row"><div><label>نام و نام خانوادگی</label><input id="editUserName"></div><div><label>ایمیل</label><input id="editUserEmail" type="email"></div></div><div class="row"><div><label>نقش کاربر</label><select id="editUserRole"><option value="cultural_manager">مدیر فرهنگی</option><option value="student">دانشجو</option><option value="observer">ناظر</option></select></div><div><label>دانشگاه</label><select id="editUserUniversity"></select></div></div><label>رمز عبور جدید (در صورت نیاز)</label><input id="editUserPassword" type="password" placeholder="برای عدم تغییر خالی بگذارید"><div class="actions"><button onclick="saveUserEdit()">ذخیره تغییرات</button><button class="secondary" onclick="closeUserModal()">انصراف</button></div><div id="editUserMsg"></div></div></div></div></div>
<div id="events" class="tab hidden"><div class="card">
<div class="section-title"><div><h2>برنامه‌های فرهنگی</h2><p class="muted">تعریف، ویرایش و انتشار برنامه‌ها بر عهده مدیر فرهنگی است.</p></div><button class="secondary" onclick="loadManagedEvents()">به‌روزرسانی فهرست</button></div>
<div class="primary-note">تاریخ‌ها را از تقویم شمسی انتخاب کنید. همه تاریخ‌ها به‌صورت خودکار در ابتدای روز (۰۰:۰۰) ثبت می‌شوند.</div>
<h3 id="eventFormTitle">تعریف برنامه جدید</h3>
<div class="row"><div><label>عنوان برنامه</label><input id="evTitle" placeholder="مثلاً اردوی فرهنگی بازدید از موزه"></div><div><label>نوع برنامه</label><select id="evCategory" onchange="updateEventFields()"><option value="workshop">کارگاه</option><option value="conference">همایش</option><option value="trip">اردو</option><option value="outing">گل‌گشت</option><option value="ceremony">مراسم</option><option value="other">سایر برنامه‌ها</option></select></div></div>
<div class="row"><div><label id="evVenueLabel">محل برگزاری</label><input id="evVenue" placeholder="محل برگزاری"></div><div><label>ظرفیت شرکت‌کنندگان</label><input id="evCapacity" type="number" min="1" value="30"></div></div>
<label>شرح برنامه</label><textarea id="evDescription" rows="3" placeholder="اهداف، مخاطبان و توضیحات اجرایی برنامه"></textarea>
<div class="row"><div><label>تاریخ شروع برنامه (شمسی)</label><input id="evStartsDate" class="jalali-date" type="text" placeholder="برای انتخاب تاریخ کلیک کنید" autocomplete="off" inputmode="none"></div><div><label>تاریخ پایان برنامه (شمسی)</label><input id="evEndsDate" class="jalali-date" type="text" placeholder="برای انتخاب تاریخ کلیک کنید" autocomplete="off" inputmode="none"></div></div>
<div class="row"><div><label>تاریخ آغاز ثبت‌نام (شمسی)</label><input id="evRegStartsDate" class="jalali-date" type="text" placeholder="برای انتخاب تاریخ کلیک کنید" autocomplete="off" inputmode="none"></div><div><label>تاریخ پایان ثبت‌نام (شمسی)</label><input id="evRegEndsDate" class="jalali-date" type="text" placeholder="برای انتخاب تاریخ کلیک کنید" autocomplete="off" inputmode="none"></div></div>
<h3>سیاست ثبت‌نام و قرعه‌کشی</h3>
<div class="row"><div><label>تعداد مجوز انتخاب مستقیم توسط مدیر (بدون قرعه‌کشی)</label><input id="evManagerQuota" type="number" min="0" value="0"><small class="muted">تعداد سهمیه‌ای که مدیر می‌تواند خارج از قرعه‌کشی تأیید کند.</small></div><div><label><input id="evGroupAllowed" type="checkbox" style="width:auto;margin:0 8px 0 0">امکان رزرو گروهی فعال باشد</label><label>حداکثر تعداد اعضای هر گروه</label><input id="evMaxGroupSize" type="number" min="1" value="1"></div></div>
<div class="row"><div><label><input id="evLotteryEnabled" type="checkbox" checked style="width:auto;margin:0 8px 0 0">قرعه‌کشی برای متقاضیان باقی‌مانده فعال باشد</label></div><div><label><input id="evRequiresApproval" type="checkbox" style="width:auto;margin:0 8px 0 0">ثبت‌نام نیازمند تأیید مدیر باشد</label></div></div>
<h3>عوامل مؤثر بر ضریب شانس قرعه‌کشی</h3>
<p class="muted">برای هر برنامه، عنوان عامل و ضریب تأثیر آن را تعریف کنید؛ مانند «عضویت فعال در تشکل» با ضریب ۱٫۲ یا «مشارکت فرهنگی» با ضریب ۱٫۱. این موارد شرط حداقل امتیاز یا مانع ثبت‌نام نیستند.</p>
<div id="lotteryFactorsList"></div><button type="button" class="secondary" onclick="addLotteryFactor()">افزودن عامل جدید +</button>
<div class="row"><div><label>وضعیت برنامه</label><select id="evStatus"><option value="draft">پیش‌نویس</option><option value="published">منتشرشده</option><option value="cancelled">لغوشده</option><option value="completed">پایان‌یافته</option></select></div><div class="actions" style="align-items:end"><button onclick="saveManagedEvent()" id="eventSaveButton">ثبت برنامه</button><button class="secondary hidden" id="eventCancelEdit" onclick="resetEventForm()">انصراف از ویرایش</button></div></div>
<div id="eventFormMsg"></div><h3>برنامه‌های ثبت‌شده</h3><div id="managedEventsList" class="table-wrap">در حال دریافت...</div>
<h3>مدیریت متقاضیان و قرعه‌کشی وزنی</h3><div class="row"><div><label>انتخاب برنامه</label><select id="lotteryEventSelect"></select></div><div class="actions" style="align-items:end"><button class="secondary" onclick="loadLotteryApplicants()">نمایش متقاضیان</button><button onclick="runEventLottery()">اجرای قرعه‌کشی</button><button class="secondary" onclick="loadLotteryResults()">نمایش نتایج</button></div></div><p class="muted">مدیر می‌تواند سوابق دانشجو را بررسی و عوامل تعریف‌شده برای هر برنامه را تأیید کند. قرعه‌کشی فقط یک‌بار برای هر برنامه اجرا می‌شود و نتیجه آن ثبت می‌گردد.</p><div id="lotteryApplicants" class="table-wrap"></div><div id="lotteryMsg"></div>
<h3>امتیازدهی ارزیابی برنامه</h3><p class="muted">این امتیازدهی برای ارزیابی و گزارش عملکرد است و با ضرایب شانس قرعه‌کشی تفاوت دارد.</p><div class="row"><div><label>برنامه</label><select id="scoreEvent"></select></div><div class="actions" style="align-items:end"><button class="secondary" onclick="loadScoring()">بارگذاری معیارها و شرکت‌کنندگان</button></div></div><div class="row"><div><label>عنوان معیار</label><input id="criterionName"></div><div><label>شرح معیار</label><input id="criterionDesc"></div><div><label>وزن معیار</label><input id="criterionWeight" type="number" min="1" max="1000" value="1"></div><div><label>حداکثر امتیاز</label><input id="criterionMax" type="number" min="1" max="1000" value="100"></div></div><button class="secondary" onclick="addCriterion()">افزودن معیار</button><div id="criteriaList"></div><div class="row"><div><label>شرکت‌کننده</label><select id="registrationSelect"></select></div><div class="actions" style="align-items:end"><button onclick="saveScores()">ذخیره امتیازها</button></div></div><div id="scoreInputs"></div><div id="scoreResults"></div>
<h3>بررسی درخواست‌های دانشجویی</h3><button class="secondary" onclick="loadPendingStudents()">بارگذاری دانشجویان در انتظار تأیید</button><div id="pendingStudentsList" class="table-wrap"></div>
</div></div>
<div id="reports" class="tab hidden"><div class="card"><h2>گزارش رویداد</h2><label>رویداد</label><select id="reportEvent"></select><button onclick="loadReport()">دریافت گزارش</button><div id="reportData"></div><h3>مدیریت بازخوردها</h3><button class="secondary" onclick="loadFeedbackModeration()">بارگذاری بازخوردها</button><div id="feedbackModeration"></div></div></div>
<div id="notifications" class="tab hidden"><div class="card"><h2>ارسال اعلان رویدادی</h2><label>رویداد</label><select id="notifyEvent"></select><label>عنوان</label><input id="notifyTitle"><label>متن اعلان</label><textarea id="notifyBody" rows="4"></textarea><button onclick="sendEventNotification()">ارسال به شرکت‌کنندگان</button><div id="notifyMsg"></div></div></div>
<div id="albums" class="tab hidden"><div class="card"><h2>مدیریت آلبوم تصاویر</h2><label>رویداد</label><select id="albumEvent"></select><div class="row"><div><label>عنوان آلبوم</label><input id="albumTitle" placeholder="تصاویر مراسم"></div><div><label>سطح دسترسی</label><select id="albumVisibility"><option value="public">عمومی</option><option value="participants">شرکت‌کنندگان</option><option value="private">خصوصی</option></select></div></div><button onclick="createAlbum()">ایجاد آلبوم</button><div id="albumsList"></div></div></div>
</section></div>
<script>
const API='/api/v1';let token=localStorage.getItem('hg_token')||'';let events=[];let isSuperAdmin=false, universities=[];const $=id=>document.getElementById(id);const headers=()=>({'Accept':'application/json','Authorization':'Bearer '+token});
let loaderDepth=0;
async function api(path,opts={}){showLoader('در حال انجام عملیات...');try{let h={...headers(),...(opts.headers||{})};if(!(opts.body instanceof FormData)&&opts.body)h['Content-Type']='application/json';let r=await fetch(API+path,{...opts,headers:h});let d=await r.json().catch(()=>({}));if(!r.ok){let detail=d.errors?Object.values(d.errors).flat().join(' | '):'';throw Error(d.message||(detail||'خطا در ارتباط با سرور ('+r.status+')'))}return d}finally{hideLoader()}}
function msg(id,text,bad=false){$(id).innerHTML='<div class="msg '+(bad?'danger':'')+'">'+esc(text)+'</div>'}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function login(){showLoader('در حال بررسی اطلاعات ورود...');$('loginButton').disabled=true;try{let d=await api('/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('email').value,password:$('password').value})});token=d.token;localStorage.setItem('hg_token',token);await boot()}catch(e){$('loginMsg').textContent=e.message}finally{hideLoader();$('loginButton').disabled=false}}
function logout(){localStorage.removeItem('hg_token');token='';$('app').classList.add('hidden');$('login').classList.remove('hidden');$('logout').classList.add('hidden')}
async function boot(){showLoader('در حال آماده‌سازی میز کار...');try{let p=await api('/profile');let u=p.user||p;let roles=(u.roles||[]).map(r=>r.name);let uniRoles=u.university_roles||u.universityRoles||[];let isManager=roles.includes('cultural_manager')||uniRoles.some(r=>(r.role?.name||r.name)==='cultural_manager'&&r.is_active!==false);await loadUserSetup();$('who').textContent=(u.name||'مدیر سامانه')+(isSuperAdmin?' | مدیر ارشد':'');$('login').classList.add('hidden');$('app').classList.remove('hidden');$('logout').classList.remove('hidden');$('eventsNav').classList.toggle('hidden',!isManager);await loadDashboard();if(isManager){await loadManagedEvents();await loadPendingStudents();}}catch(e){logout();$('loginMsg').textContent=e.message}finally{hideLoader()}}
function openTab(id){const b=document.querySelector(`[data-tab=\"${id}\"]`);if(b)b.click()}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('hidden',x.id!==b.dataset.tab));if(b.dataset.tab==='events'){loadManagedEvents();loadPendingStudents();}if(b.dataset.tab==='universities')loadUniversities();if(b.dataset.tab==='users')loadUsers();if(b.dataset.tab==='reports')fillEvents();if(b.dataset.tab==='albums')loadAlbums()});
async function loadDashboard(){try{let d=await api('/reports/dashboard');let s=d.summary||{};$('metrics').innerHTML=Object.entries({'کل برنامه‌ها':s.events,'رویدادهای منتشرشده':s.published_events,'ثبت‌نام‌ها':s.registrations,'ثبت‌نام قطعی':s.confirmed_registrations,'فهرست انتظار':s.waitlist,'بازخوردها':s.feedback_count,'میانگین رضایت':s.average_rating}).map(([k,v])=>`<div class="card"><div class="muted">${k}</div><div class="metric">${v??0}</div></div>`).join('');events=(d.events?.data||[]);renderEventOptions();$('eventList').innerHTML=events.length?`<table><tr><th>رویداد</th><th>ثبت‌نام</th><th>بازخورد</th><th>وضعیت</th></tr>${events.map(e=>`<tr><td>${esc(e.title)}</td><td>${e.registrations_count??0}</td><td>${e.feedbacks_count??0}</td><td>${esc(e.status)}</td></tr>`).join('')}</table>`:'رویدادی یافت نشد.'}catch(e){msg('eventList',e.message,true)}}
function renderEventOptions(){['reportEvent','notifyEvent','albumEvent','scoreEvent'].forEach(id=>$(id).innerHTML=events.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join(''));}
async function fillEvents(){if(!events.length)await loadDashboard();renderEventOptions()}
async function loadScoring(){await fillEvents();if($('scoreEvent').value)await changeScoreEvent()};$('scoreEvent').onchange=changeScoreEvent;
async function changeScoreEvent(){let id=$('scoreEvent').value;if(!id)return;try{let [c,r]=await Promise.all([api(`/events/${id}/scoring-criteria`),api(`/events/${id}/scoring-results`)]);let criteria=c.criteria||[];window.criteria=criteria;$('criteriaList').innerHTML=criteria.map(x=>`<div class="msg">${esc(x.name)} — وزن ${x.weight} — سقف ${x.max_score}</div>`).join('')||'<p class="muted">معیاری ثبت نشده است.</p>';let rows=r.results?.data||[];$('registrationSelect').innerHTML=rows.map(x=>`<option value="${x.id}">${esc(x.user?.name||'کاربر')} (کد ${x.id})</option>`).join('');$('scoreInputs').innerHTML=criteria.map(x=>`<div class="row"><label>${esc(x.name)} (۰ تا ${x.max_score})<input type="number" min="0" max="${x.max_score}" data-criterion="${x.id}" value="0"></label></div>`).join('');$('scoreResults').innerHTML=rows.length?`<table><tr><th>شرکت‌کننده</th><th>امتیاز نهایی</th></tr>${rows.map(x=>`<tr><td>${esc(x.user?.name||'—')}</td><td>${x.total_score??0}</td></tr>`).join('')}</table>`:'ثبت‌نامی برای امتیازدهی وجود ندارد.'}catch(e){msg('criteriaList',e.message,true)}}
async function addCriterion(){try{let id=$('scoreEvent').value;await api(`/events/${id}/scoring-criteria`,{method:'POST',body:JSON.stringify({name:$('criterionName').value,description:$('criterionDesc').value,weight:+$('criterionWeight').value,max_score:+$('criterionMax').value,is_active:true})});$('criterionName').value='';await changeScoreEvent()}catch(e){alert(e.message)}}
async function saveScores(){try{let scores=[...document.querySelectorAll('[data-criterion]')].map(x=>({criterion_id:+x.dataset.criterion,score:+x.value}));await api(`/events/${$('scoreEvent').value}/registrations/${$('registrationSelect').value}/scores`,{method:'POST',body:JSON.stringify({scores})});await changeScoreEvent();alert('امتیازها ذخیره شد.')}catch(e){alert(e.message)}}
async function loadReport(){try{let d=await api(`/reports/events/${$('reportEvent').value}`);let r=d.report;$('reportData').innerHTML=`<div class="grid"><div class="card">ثبت‌نام‌ها: ${r.registrations.reduce((a,x)=>a+x.count,0)}</div><div class="card">میانگین امتیاز: ${r.scores.average??0}</div><div class="card">بیشترین امتیاز: ${r.scores.maximum??0}</div><div class="card">تعداد بازخورد: ${r.feedback.count}</div><div class="card">میانگین رضایت: ${r.feedback.average_rating}</div></div><h3>وضعیت ثبت‌نام</h3><table><tr><th>وضعیت</th><th>تعداد</th></tr>${r.registrations.map(x=>`<tr><td>${esc(x.status)}</td><td>${x.count}</td></tr>`).join('')}</table>`}catch(e){msg('reportData',e.message,true)}}
async function loadFeedbackModeration(){try{const id=$('reportEvent').value;const d=await api(`/events/${id}/feedback-management`);const rows=d.feedbacks?.data||[];$('feedbackModeration').innerHTML=rows.length?`<table><tr><th>دانشجو</th><th>امتیاز</th><th>نظر</th><th>وضعیت نمایش</th><th>عملیات</th></tr>${rows.map(f=>`<tr><td>${f.is_anonymous?'ناشناس':esc(f.user?.name||'—')}</td><td>${f.rating}/5</td><td>${esc(f.comment||'—')}</td><td>${f.is_visible?'نمایش داده می‌شود':'پنهان'}</td><td><button class="secondary" onclick="moderateFeedback(${f.id},${!f.is_visible})">${f.is_visible?'پنهان‌کردن':'تأیید و نمایش'}</button></td></tr>`).join('')}</table>`:'بازخوردی ثبت نشده است.'}catch(e){msg('feedbackModeration',e.message,true)}}
async function moderateFeedback(id,visible){try{await api(`/events/${$('reportEvent').value}/feedback/${id}`,{method:'PATCH',body:JSON.stringify({is_visible:visible})});await loadFeedbackModeration()}catch(e){msg('feedbackModeration',e.message,true)}}
async function sendEventNotification(){try{let d=await api(`/events/${$('notifyEvent').value}/notifications`,{method:'POST',body:JSON.stringify({title:$('notifyTitle').value,body:$('notifyBody').value})});msg('notifyMsg',d.message||'اعلان ارسال شد.')}catch(e){msg('notifyMsg',e.message,true)}}
async function loadAlbums(){await fillEvents();if($('albumEvent').value)await refreshAlbums()}$('albumEvent').onchange=refreshAlbums;
async function refreshAlbums(){try{let d=await api(`/events/${$('albumEvent').value}/albums`);$('albumsList').innerHTML=(d.albums?.data||d.albums||[]).map(a=>`<div class="card"><div class="section-title"><b>${esc(a.title)}</b><span class="pill">${esc(a.visibility)}</span></div><div class="muted">${(a.media||[]).length} تصویر</div><label>افزودن تصاویر</label><input type="file" multiple accept="image/jpeg,image/png,image/webp" id="files-${a.id}"><button onclick="uploadMedia(${a.id})">بارگذاری تصاویر</button><div class="grid">${(a.media||[]).map(m=>`<div><img src="${esc(m.url||('/storage/'+m.file_path))}" style="width:100%;border-radius:8px"><button class="secondary" onclick="deleteMedia(${a.id},${m.id})">حذف تصویر</button></div>`).join('')}</div></div>`).join('')||'<p class="muted">آلبومی ایجاد نشده است.</p>'}catch(e){msg('albumsList',e.message,true)}}
async function createAlbum(){try{await api(`/events/${$('albumEvent').value}/albums`,{method:'POST',body:JSON.stringify({title:$('albumTitle').value,visibility:$('albumVisibility').value})});$('albumTitle').value='';await refreshAlbums()}catch(e){alert(e.message)}}
async function uploadMedia(id){try{let fd=new FormData();[...$('files-'+id).files].forEach(f=>fd.append('files[]',f));await api(`/events/${$('albumEvent').value}/albums/${id}/media`,{method:'POST',body:fd});await refreshAlbums()}catch(e){alert(e.message)}}
async function deleteMedia(album,media){if(!confirm('تصویر حذف شود؟'))return;try{await api(`/events/${$('albumEvent').value}/albums/${album}/media/${media}`,{method:'DELETE'});await refreshAlbums()}catch(e){alert(e.message)}}

async function loadUserSetup(){
 const p=await api('/profile');const u=p.user||p;
 isSuperAdmin=Boolean(p.permissions?.is_super_admin || u.is_super_admin || String(u.email||'').toLowerCase()==='mahmia.developer@gmail.com');
 $('usersNav').classList.toggle('hidden',!isSuperAdmin);$('adminQuickActions').classList.toggle('hidden',!isSuperAdmin);
 $('universitiesNav').classList.toggle('hidden',!isSuperAdmin);if(isSuperAdmin){$('universitiesNav').classList.remove('hidden');$('usersNav').classList.remove('hidden');}
 if(!isSuperAdmin)return;
 const d=await api('/universities');universities=d.data||d.universities||[];
 $('newUserUniversity').innerHTML='<option value="">انتخاب دانشگاه</option>'+universities.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');
 $('editUserUniversity').innerHTML='<option value="">انتخاب دانشگاه</option>'+universities.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');
 toggleUserUniversity();
 return u;
}
function toggleUserUniversity(){$('newUniversityWrap').classList.remove('hidden');}
async function createUser(){try{let payload={name:$('newUserName').value.trim(),email:$('newUserEmail').value.trim(),password:$('newUserPassword').value,role:$('newUserRole').value};if(!$('newUserUniversity').value){msg('userFormMsg','ابتدا دانشگاه را انتخاب کنید.',true);return}payload.university_id=+$('newUserUniversity').value;let d=await api('/users',{method:'POST',body:JSON.stringify(payload)});msg('userFormMsg',d.message||'کاربر ایجاد شد.');$('newUserName').value='';$('newUserEmail').value='';$('newUserPassword').value='';await loadUsers();}catch(e){msg('userFormMsg',e.message,true)}}
async function loadUsers(){if(!isSuperAdmin)return;try{let q=$('userSearch').value.trim();let d=await api('/users'+(q?'?search='+encodeURIComponent(q):''));let rows=d.data||[];$('usersList').innerHTML=rows.length?`<div style="overflow:auto"><table><tr><th>نام</th><th>ایمیل</th><th>نقش</th><th>دانشگاه</th><th>وضعیت</th><th>عملیات</th></tr>${rows.map(u=>{let a=(u.university_roles||[]).find(x=>x.is_active)||u.university_roles?.[0];let role=a?.role?.name|| (u.is_super_admin?'مدیر ارشد':'بدون نقش');let labels={cultural_manager:'مدیر فرهنگی',student:'دانشجو',observer:'ناظر',super_admin:'مدیر ارشد'};return `<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(labels[role]||role)}</td><td>${esc(a?.university?.name||'—')}</td><td>${u.is_active===false?'غیرفعال':'فعال'}</td><td>${u.is_super_admin?'—':`<button class="secondary" onclick="editUser(${u.id},${JSON.stringify(u.name).replace(/'/g,'&#39;')},${JSON.stringify(u.email).replace(/'/g,'&#39;')},'${role}',${a?.university_id||''})">ویرایش</button> <button class="${u.is_active===false?'':'secondary'}" onclick="setUserActive(${u.id},${u.is_active===false})">${u.is_active===false?'فعال‌سازی':'غیرفعال‌سازی'}</button>`}</td></tr>`}).join('')}</table></div>`:'کاربری یافت نشد.';}catch(e){msg('usersList',e.message,true)}}
function editUser(id,name,email,role,universityId){$('editUserId').value=id;$('editUserName').value=name;$('editUserEmail').value=email;$('editUserRole').value=['cultural_manager','student','observer'].includes(role)?role:'student';$('editUserUniversity').innerHTML='<option value="">انتخاب دانشگاه</option>'+universities.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('editUserUniversity').value=universityId||'';$('editUserPassword').value='';$('userEditModal').classList.remove('hidden');$('editUserMsg').innerHTML=''}
function closeUserModal(){$('userEditModal').classList.add('hidden')}
async function saveUserEdit(){let role=$('editUserRole').value,uni=$('editUserUniversity').value,payload={name:$('editUserName').value.trim(),email:$('editUserEmail').value.trim(),role,university_id:uni?+uni:null};if($('editUserPassword').value)payload.password=$('editUserPassword').value;if(!uni){msg('editUserMsg','برای تخصیص نقش، انتخاب دانشگاه الزامی است.',true);return}try{await api('/users/'+$('editUserId').value,{method:'PUT',body:JSON.stringify(payload)});closeUserModal();await loadUsers()}catch(e){msg('editUserMsg',e.message,true)}}
async function setUserActive(id,active){if(!confirm(active?'حساب فعال شود؟':'حساب غیرفعال شود؟'))return;try{await api('/users/'+id+'/status',{method:'PATCH',body:JSON.stringify({is_active:active})});await loadUsers()}catch(e){alert(e.message)}}




async function loadLotteryApplicants(){const id=$('lotteryEventSelect').value;if(!id)return;try{const d=await api(`/events/${id}/lottery-applicants`);const regs=d.registrations||[],factors=d.factors||[],awards=d.awards||{};window.lotteryPolicy=d.policy||{};const labels={pending:'در انتظار قرعه‌کشی',pending_approval:'منتظر تأیید مدیر',confirmed:'تأییدشده',waitlisted:'فهرست انتظار',cancelled:'لغوشده',rejected:'ردشده'};$('lotteryApplicants').innerHTML=regs.length?`<table><tr><th>دانشجو</th><th>وضعیت</th><th>سوابق فرهنگی</th><th>عوامل تأییدشده</th><th>عملیات</th></tr>${regs.map(r=>{const uid=r.user_id,rs=r.user?.student_cultural_records||[],as=awards[uid]||[];return `<tr><td>${esc(r.user?.name||'—')}<br><small>${esc(r.user?.email||'')}</small></td><td>${esc(labels[r.status]||r.status)}</td><td>${rs.map(x=>`<div>${esc(x.title)} <span class="pill">${esc(x.status)}</span>${x.status==='pending'?` <button class="secondary" onclick="moderateStudentRecordFromLottery(${x.id},'verified')">تأیید</button> <button class="secondary" onclick="moderateStudentRecordFromLottery(${x.id},'rejected')">رد</button>`:''}</div>`).join('')||'—'}</td><td>${as.map(a=>`<span class="pill">${esc(a.factor_name)} × ${esc(a.coefficient)}</span>`).join(' ')||'—'}</td><td><div class="actions">${factors.map(f=>{const active=as.some(a=>a.factor_name===f.name&&a.status==='verified');return `<button class="${active?'secondary':''}" onclick="toggleLotteryFactor(${uid},decodeURIComponent('${encodeURIComponent(f.name)}'),${active?'false':'true'})">${active?'حذف':'اعمال'}: ${esc(f.name)} × ${f.coefficient}</button>`}).join('')}${['pending','pending_approval','waitlisted'].includes(r.status)&&r.selection_method!=='lottery'&&Number(window.lotteryPolicy.manager_approval_quota||0)>0?`<button onclick="managerApprove(${r.id})">انتخاب مستقیم مدیر</button>`:''}${r.status==='pending_approval'?`<button onclick="moderateRegistration(${r.id},'approve')">تأیید نهایی</button><button class="secondary" onclick="moderateRegistration(${r.id},'reject')">رد</button>`:''}</div></td></tr>`}).join('')}</table>`:'متقاضی فعالی برای این برنامه وجود ندارد.'}catch(e){msg('lotteryApplicants',e.message,true)}}
async function toggleLotteryFactor(userId,name,enable){try{await api(`/events/${$('lotteryEventSelect').value}/lottery-factor-awards`,{method:'POST',body:JSON.stringify({user_id:userId,factor_name:name,action:enable?'verify':'revoke'})});await loadLotteryApplicants()}catch(e){msg('lotteryMsg',e.message,true)}}
async function moderateStudentRecordFromLottery(id,status){try{await api(`/student-cultural-records/${id}/moderate`,{method:'PATCH',body:JSON.stringify({status})});await loadLotteryApplicants()}catch(e){msg('lotteryMsg',e.message,true)}}
async function managerApprove(id){if(!confirm('این متقاضی با سهمیه مستقیم مدیر انتخاب شود؟'))return;try{const d=await api(`/events/${$('lotteryEventSelect').value}/registrations/${id}/manager-approve`,{method:'POST'});msg('lotteryMsg',d.message);await loadLotteryApplicants()}catch(e){msg('lotteryMsg',e.message,true)}}
async function moderateRegistration(id,decision){try{const d=await api(`/events/${$('lotteryEventSelect').value}/registrations/${id}/moderate`,{method:'PATCH',body:JSON.stringify({decision})});msg('lotteryMsg',d.message);await loadLotteryApplicants()}catch(e){msg('lotteryMsg',e.message,true)}}
async function runEventLottery(){const id=$('lotteryEventSelect').value;if(!id)return;if(!confirm('قرعه‌کشی این برنامه اجرا شود؟ نتیجه پس از اجرا قابل اجرای مجدد نیست.'))return;try{const d=await api(`/events/${id}/run-lottery`,{method:'POST'});msg('lotteryMsg',`${d.message} تعداد انتخاب‌شده: ${(d.winners||[]).length} | فهرست انتظار: ${(d.waitlist||[]).length}`);await loadLotteryApplicants()}catch(e){msg('lotteryMsg',e.message,true)}}
async function loadLotteryResults(){const id=$('lotteryEventSelect').value;if(!id)return;try{const d=await api(`/events/${id}/lottery-results`);const rows=d.registrations||[];$('lotteryApplicants').innerHTML=`<h3>نتایج ثبت‌شده قرعه‌کشی</h3><table><tr><th>دانشجو</th><th>وضعیت</th><th>روش انتخاب</th><th>ضریب نهایی</th><th>رتبه</th></tr>${rows.map(r=>`<tr><td>${esc(r.user?.name||'—')}</td><td>${esc(r.status)}</td><td>${esc(r.selection_method||'—')}</td><td>${esc(r.lottery_weight||1)}</td><td>${esc(r.lottery_rank||'—')}</td></tr>`).join('')}</table>`+(d.runs||[]).map(x=>`<p class="muted">اجرا توسط ${esc(x.runner?.name||'—')} در ${esc(x.executed_at)}؛ ${x.winner_count} منتخب و ${x.waitlist_count} رزرو</p>`).join('')}catch(e){msg('lotteryApplicants',e.message,true)}}
async function loadPendingStudents(){try{const d=await api('/students/pending');const rows=d.data||[];$('pendingStudentsList').innerHTML=rows.length?`<table><tr><th>نام</th><th>ایمیل</th><th>دانشگاه</th><th>شماره دانشجویی</th><th>رشته / مقطع / ورود</th><th>عضویت‌ها و بررسی مستقل</th><th>عملیات پروفایل</th></tr>${rows.map(s=>{const recs=s.user?.student_cultural_records||[];return `<tr><td>${esc(s.user?.name||'—')}</td><td>${esc(s.user?.email||'')}</td><td>${esc(s.university?.name||'')}</td><td>${esc(s.student_number)}</td><td>${esc(s.field_of_study||'—')}<br>${esc(s.degree||'—')}<br>${esc(s.entry_year||'—')}</td><td>${recs.map(r=>`<div style="margin:5px 0"><b>${esc(r.title)}</b> <span class="pill">${esc(({pending:'در انتظار بررسی',verified:'تأییدشده',rejected:'ردشده'})[r.status]||r.status)}</span>${r.status==='pending'?`<div class="actions"><button onclick="moderateStudentRecord(${r.id},'verified')">تأیید عضویت</button><button class="secondary" onclick="moderateStudentRecord(${r.id},'rejected')">رد عضویت</button></div>`:''}</div>`).join('')||'عضویتی انتخاب نشده'}</td><td><button onclick="moderateStudent(${s.id},'active')">تأیید پروفایل</button><button class="secondary" onclick="moderateStudent(${s.id},'rejected')">رد پروفایل</button></td></tr>`}).join('')}</table>`:'درخواستی در انتظار تأیید نیست.'}catch(e){msg('pendingStudentsList',e.message,true)}}
async function moderateStudentRecord(id,status){try{const d=await api(`/student-cultural-records/${id}/moderate`,{method:'PATCH',body:JSON.stringify({status})});msg('pendingStudentsList',d.message);await loadPendingStudents()}catch(e){msg('pendingStudentsList',e.message,true)}}
async function moderateStudent(id,status){try{const d=await api(`/students/${id}/moderate`,{method:'PATCH',body:JSON.stringify({status})});msg('pendingStudentsList',d.message);await loadPendingStudents()}catch(e){msg('pendingStudentsList',e.message,true)}}

function updateEventFields(){let c=$('evCategory').value;let trip=['trip','outing'].includes(c);$('evVenueLabel').textContent=trip?(c==='trip'?'مقصد اردو':'مسیر / مقصد گل‌گشت'):'محل برگزاری';$('evVenue').placeholder=trip?'مقصد و محل بازدید':'نام محل برگزاری یا سالن'}
function slugify(s){return s.trim().toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-|-$/g,'')+'-'+Date.now().toString().slice(-6)}
let editingEventId=null;
const jalaliIntl = new Intl.DateTimeFormat('en-US-u-ca-persian', {year:'numeric',month:'numeric',day:'numeric',timeZone:'UTC'});
function jalaliParts(date){const parts=jalaliIntl.formatToParts(date);const get=k=>Number(parts.find(p=>p.type===k)?.value||0);return {year:get('year'),month:get('month'),day:get('day')}}
function jalaliMonthDays(year,month){const start=new Date(Date.UTC(year+621,2,18));const found=[];for(let i=0;i<370;i++){const d=new Date(start.getTime()+i*86400000);const p=jalaliParts(d);if(p.year===year&&p.month===month)found.push({date:d,day:p.day})}return found}
function gregorianIso(date){return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}
function jalaliToGregorian(value){const v=normalizeDigits(value).trim();const m=v.match(/^(\d{4})[\/.\-](\d{1,2})[\/.\-](\d{1,2})$/);if(!m)throw Error('تاریخ را از تقویم شمسی انتخاب کنید.');const jy=+m[1],jm=+m[2],jd=+m[3];if(jm<1||jm>12||jd<1||jd>31)throw Error('تاریخ شمسی معتبر نیست.');const days=jalaliMonthDays(jy,jm);const hit=days.find(x=>x.day===jd);if(!hit)throw Error('تاریخ شمسی معتبر نیست.');return gregorianIso(hit.date)}
function gregorianToJalali(value){if(!value)return '';const m=String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return '';const d=new Date(Date.UTC(+m[1],+m[2]-1,+m[3]));const p=jalaliParts(d);return `${p.year}/${String(p.month).padStart(2,'0')}/${String(p.day).padStart(2,'0')}`}
function normalizeDigits(v){return String(v||'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d))}
let activeJalaliInput=null, activeJalaliMonth=null;
function closeJalaliPicker(){const p=document.getElementById('jalaliPicker');if(p)p.remove();activeJalaliInput=null}
function renderJalaliPicker(){const input=activeJalaliInput;if(!input)return;let p=document.getElementById('jalaliPicker');if(!p){p=document.createElement('div');p.id='jalaliPicker';p.className='jalali-picker';document.body.appendChild(p)}const {year,month}=activeJalaliMonth;const names=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];const days=jalaliMonthDays(year,month);const first=days[0]?.date;const offset=first?(first.getUTCDay()+1)%7:0;const selected=normalizeDigits(input.value).match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);let html=`<div class="jp-head"><button type="button" onclick="event.stopPropagation();shiftJalaliMonth(-1)">ماه قبل</button><b>${names[month-1]} ${year}</b><button type="button" onclick="event.stopPropagation();shiftJalaliMonth(1)">ماه بعد</button></div><div class="jp-grid">${['ش','ی','د','س','چ','پ','ج'].map(x=>`<span>${x}</span>`).join('')}`;for(let i=0;i<offset;i++)html+='<i></i>';for(const x of days){const isSelected=selected&&+selected[1]===year&&+selected[2]===month&&+selected[3]===x.day;html+=`<button type="button" class="${isSelected?'selected':''}" onclick="event.stopPropagation();chooseJalaliDate(${year},${month},${x.day})">${x.day}</button>`}html+=`</div><div class="jp-foot"><button type="button" onclick="event.stopPropagation();chooseTodayJalali()">امروز</button><button type="button" onclick="event.stopPropagation();closeJalaliPicker()">بستن</button></div>`;p.innerHTML=html;const r=input.getBoundingClientRect();p.style.top=Math.min(r.bottom+5,window.innerHeight-320)+'px';p.style.left=Math.max(8,Math.min(r.left,window.innerWidth-298))+'px'}
function shiftJalaliMonth(delta){let y=activeJalaliMonth.year,m=activeJalaliMonth.month+delta;if(m<1){m=12;y--}if(m>12){m=1;y++}activeJalaliMonth={year:y,month:m};renderJalaliPicker()}
function chooseJalaliDate(y,m,d){if(activeJalaliInput)activeJalaliInput.value=`${y}/${String(m).padStart(2,'0')}/${String(d).padStart(2,'0')}`;closeJalaliPicker()}
function chooseTodayJalali(){const n=new Date();const p=jalaliParts(new Date(Date.UTC(n.getFullYear(),n.getMonth(),n.getDate())));chooseJalaliDate(p.year,p.month,p.day)}
function openJalaliPicker(input){activeJalaliInput=input;const current=normalizeDigits(input.value).match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);const p=current?{year:+current[1],month:+current[2]}:jalaliParts(new Date());activeJalaliMonth={year:p.year,month:p.month};renderJalaliPicker()}
function initJalaliPickers(){document.querySelectorAll('.jalali-date').forEach(input=>{input.setAttribute('readonly','readonly');input.setAttribute('placeholder','برای انتخاب تاریخ کلیک کنید');input.onclick=()=>openJalaliPicker(input);input.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openJalaliPicker(input)}}});if(!window.jalaliOutsideBound){document.addEventListener('click',e=>{if(!e.target.closest('.jalali-picker')&&!e.target.closest('.jalali-date'))closeJalaliPicker()});window.addEventListener('resize',closeJalaliPicker);window.jalaliOutsideBound=true}}
function setEventDate(prefix,value){if(!value)return;$(prefix+'Date').value=gregorianToJalali(String(value));}
function eventDateTime(prefix){return jalaliToGregorian($(prefix+'Date').value)+'T00:00:00';}
function addLotteryFactor(name='',coefficient='1.0'){const wrap=document.createElement('div');wrap.className='row lottery-factor-row';wrap.style.cssText='align-items:end;margin:8px 0;padding:10px;background:#f7fafc;border-radius:10px';wrap.innerHTML=`<div><label>عنوان عامل مؤثر</label><input class="lottery-factor-name" maxlength="120" placeholder="مثلاً عضویت فعال در تشکل" value="${esc(name)}"></div><div><label>ضریب تأثیر</label><input class="lottery-factor-coefficient" type="number" min="0.01" max="100" step="0.01" value="${esc(coefficient)}"></div><div style="flex:0 0 auto"><button type="button" class="secondary danger" onclick="this.closest('.lottery-factor-row').remove()">حذف</button></div>`;$('lotteryFactorsList').appendChild(wrap)}
function readLotteryFactors(){return [...document.querySelectorAll('.lottery-factor-row')].map(row=>({name:row.querySelector('.lottery-factor-name').value.trim(),coefficient:Number(row.querySelector('.lottery-factor-coefficient').value)})).filter(x=>x.name)}
function renderLotteryFactors(items=[]){$('lotteryFactorsList').innerHTML='';(Array.isArray(items)?items:[]).forEach(x=>addLotteryFactor(x.name??'',x.coefficient??'1.0'))}
function getEventPayload(){let title=$('evTitle').value.trim();if(!title)throw Error('عنوان برنامه را وارد کنید.');const factors=readLotteryFactors();if(factors.some(x=>!Number.isFinite(x.coefficient)||x.coefficient<=0||x.coefficient>100))throw Error('ضریب هر عامل باید عددی بزرگ‌تر از صفر و حداکثر ۱۰۰ باشد.');if(new Set(factors.map(x=>x.name)).size!==factors.length)throw Error('عنوان عوامل قرعه‌کشی نباید تکراری باشد.');return {title,slug:editingEventId?undefined:slugify(title),category:$('evCategory').value,venue:$('evVenue').value.trim(),description:$('evDescription').value,capacity:+$('evCapacity').value,starts_at:eventDateTime('evStarts'),ends_at:eventDateTime('evEnds'),registration_starts_at:eventDateTime('evRegStarts'),registration_ends_at:eventDateTime('evRegEnds'),status:$('evStatus').value,is_group_registration_allowed:$('evGroupAllowed').checked,policy:{manager_approval_quota:+$('evManagerQuota').value||0,max_group_size:$('evGroupAllowed').checked?(+$('evMaxGroupSize').value||1):1,lottery_enabled:$('evLotteryEnabled').checked,requires_approval:$('evRequiresApproval').checked,rules:{lottery_factors:factors}}}}
async function loadManagedEvents(){try{let d=await api('/managed-events');let rows=d.data||[];$('lotteryEventSelect').innerHTML=rows.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('');let statuses={draft:'پیش‌نویس',published:'منتشرشده',cancelled:'لغوشده',completed:'پایان‌یافته'};let cats={workshop:'کارگاه',conference:'همایش',trip:'اردو',outing:'گل‌گشت',ceremony:'مراسم',other:'سایر'};$('managedEventsList').innerHTML=rows.length?`<table><thead><tr><th>عنوان برنامه</th><th>نوع</th><th>دانشگاه</th><th>زمان شروع</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.title)}</td><td>${esc(cats[e.category]||e.category)}</td><td>${esc(e.university?.name||'—')}</td><td>${esc(e.starts_at||'—')}</td><td><span class="pill">${esc(statuses[e.status]||e.status)}</span></td><td><div class="actions"><button class="secondary" onclick="editManagedEvent(${e.id})">ویرایش</button>${e.status==='draft'?`<button onclick="changeManagedEventStatus(${e.id},'published')">انتشار</button>`:''}${e.status==='published'?`<button class="secondary" onclick="changeManagedEventStatus(${e.id},'draft')">بازگشت به پیش‌نویس</button>`:''}</div></td></tr>`).join('')}</tbody></table>`:'هنوز برنامه‌ای ثبت نشده است.'}catch(e){msg('managedEventsList',e.message,true)}}
async function editManagedEvent(id){try{let d=await api('/managed-events/'+id);let e=d.event||d;editingEventId=id;$('evTitle').value=e.title||'';$('evCategory').value=e.category||'other';updateEventFields();$('evVenue').value=e.venue||'';$('evCapacity').value=e.capacity||30;$('evDescription').value=e.description||'';setEventDate('evStarts',e.starts_at);setEventDate('evEnds',e.ends_at);setEventDate('evRegStarts',e.registration_starts_at);setEventDate('evRegEnds',e.registration_ends_at);$('evStatus').value=e.status||'draft';$('evGroupAllowed').checked=!!e.is_group_registration_allowed;renderLotteryFactors(e.policy?.rules?.lottery_factors||[]);$('evManagerQuota').value=e.policy?.manager_approval_quota??0;$('evMaxGroupSize').value=e.policy?.max_group_size??1;$('evLotteryEnabled').checked=e.policy?.lottery_enabled!==false;$('evRequiresApproval').checked=!!e.policy?.requires_approval;$('eventFormTitle').textContent='ویرایش برنامه فرهنگی';$('eventSaveButton').textContent='ذخیره تغییرات';$('eventCancelEdit').classList.remove('hidden');$('eventFormMsg').innerHTML='';$('eventFormTitle').scrollIntoView({behavior:'smooth',block:'center'})}catch(e){msg('eventFormMsg',e.message,true)}}
async function saveManagedEvent(){try{let payload=getEventPayload();if(editingEventId){delete payload.slug;await api('/events/'+editingEventId,{method:'PUT',body:JSON.stringify(payload)});msg('eventFormMsg','تغییرات برنامه ذخیره شد.')}else{await api('/events',{method:'POST',body:JSON.stringify(payload)});msg('eventFormMsg','برنامه با موفقیت ثبت شد.')}resetEventForm();await loadManagedEvents()}catch(e){msg('eventFormMsg',e.message,true)}}
async function changeManagedEventStatus(id,status){let labels={draft:'پیش‌نویس',published:'منتشرشده',cancelled:'لغوشده',completed:'پایان‌یافته'};if(!confirm('وضعیت برنامه به «'+labels[status]+'» تغییر کند؟'))return;try{await api('/events/'+id,{method:'PATCH',body:JSON.stringify({status})});await loadManagedEvents();msg('eventFormMsg','وضعیت برنامه تغییر کرد.')}catch(e){msg('eventFormMsg',e.message,true)}}
function resetEventForm(){editingEventId=null;['evTitle','evVenue','evDescription','evStartsDate','evEndsDate','evRegStartsDate','evRegEndsDate'].forEach(id=>$(id).value='');$('evManagerQuota').value=0;renderLotteryFactors([]);$('evGroupAllowed').checked=false;$('evMaxGroupSize').value=1;$('evLotteryEnabled').checked=true;$('evRequiresApproval').checked=false;$('evCapacity').value=30;$('evCategory').value='workshop';$('evStatus').value='draft';updateEventFields();$('eventFormTitle').textContent='تعریف برنامه جدید';$('eventSaveButton').textContent='ثبت برنامه';$('eventCancelEdit').classList.add('hidden')}

window.hgEditingUniversityId = null;
function showLoader(text){loaderDepth++;let l=$('globalLoader');if(!l){l=document.createElement('div');l.id='globalLoader';l.className='loader';l.innerHTML='<div class="brand-mark">🤝</div><div class="track"><div class="bar"></div></div><p id="loaderText"></p>';document.body.appendChild(l)}$('loaderText').textContent=text||'در حال انجام عملیات...';l.classList.remove('hidden')}
function hideLoader(){loaderDepth=Math.max(0,loaderDepth-1);const l=$('globalLoader');if(l&&loaderDepth===0)l.classList.add('hidden')}
async function loadUniversities(){try{let d=await api('/universities');universities=d.data||[];$('universitiesList').innerHTML=universities.length?`<table><thead><tr><th>نام دانشگاه</th><th>کد</th><th>شهر</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${universities.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.code)}</td><td>${esc(u.city||'—')}</td><td>${u.is_active?'فعال':'غیرفعال'}</td><td><button class="secondary" onclick="editUniversity(${u.id})">ویرایش</button></td></tr>`).join('')}</tbody></table>`:'دانشگاهی ثبت نشده است.'}catch(e){msg('universitiesList',e.message,true)}}
async function saveUniversity(){let payload={name:$('uniName').value.trim(),code:$('uniCode').value.trim(),city:$('uniCity').value.trim()};try{let path=window.hgEditingUniversityId?'/universities/'+window.hgEditingUniversityId:'/universities';await api(path,{method:window.hgEditingUniversityId?'PUT':'POST',body:JSON.stringify(payload)});msg('uniMsg',window.hgEditingUniversityId?'اطلاعات دانشگاه به‌روزرسانی شد.':'دانشگاه با موفقیت ثبت شد.');resetUniversityForm();await loadUniversities();await loadUserSetup()}catch(e){msg('uniMsg',e.message,true)}}
async function editUniversity(id){try{let d=await api('/universities/'+id);let u=d.university;$('uniName').value=u.name||'';$('uniCode').value=u.code||'';$('uniCity').value=u.city||'';window.hgEditingUniversityId=id;$('uniSave').textContent='ذخیره تغییرات';$('uniCancel').classList.remove('hidden');$('uniName').focus()}catch(e){msg('uniMsg',e.message,true)}}
function resetUniversityForm(){window.hgEditingUniversityId=null;['uniName','uniCode','uniCity'].forEach(id=>$(id).value='');$('uniSave').textContent='ثبت دانشگاه';$('uniCancel').classList.add('hidden')}

renderLotteryFactors([]);initJalaliPickers();if(token)boot();
</script></body></html>
